import { ArrowDownRightIcon, ArrowUpRightIcon, PlusIcon } from '@phosphor-icons/react';
import {
  Badge,
  Button,
  Group,
  SimpleGrid,
  Stack,
  Surface,
  Table,
  Text,
  Title,
} from '@mantine/core';
import { OrderStatus, orders, stats } from './data';
import classes from './Dashboard.module.css';

const statusColors: Record<OrderStatus, string> = {
  Paid: 'green',
  Pending: 'yellow',
  Refunded: 'red',
};

export function Dashboard() {
  const statCards = stats.map((stat) => {
    const DiffIcon = stat.diff > 0 ? ArrowUpRightIcon : ArrowDownRightIcon;

    return (
      <Surface key={stat.label} level={0} withBorder p="md">
        <Text className={classes.statLabel}>{stat.label}</Text>
        <Group justify="space-between" align="flex-end" wrap="nowrap" mt="xs">
          <Text className={classes.statValue}>{stat.value}</Text>
          <Group gap={4} wrap="nowrap" c={stat.diff > 0 ? 'teal' : 'red'}>
            <Text size="sm" fw={500}>
              {stat.diff > 0 ? '+' : ''}
              {stat.diff}%
            </Text>
            <DiffIcon size={16} />
          </Group>
        </Group>
      </Surface>
    );
  });

  const rows = orders.map((order) => (
    <Table.Tr key={order.id}>
      <Table.Td>{order.id}</Table.Td>
      <Table.Td>{order.customer}</Table.Td>
      <Table.Td>{order.date}</Table.Td>
      <Table.Td>
        <Badge color={statusColors[order.status]}>{order.status}</Badge>
      </Table.Td>
      <Table.Td ta="right">{order.amount}</Table.Td>
    </Table.Tr>
  ));

  return (
    <Stack gap="lg">
      <Group justify="space-between">
        <div>
          <Title order={2} c="var(--mantine-color-bright)">
            Dashboard
          </Title>
          <Text size="sm">Overview of your store for the last 30 days</Text>
        </div>
        <Button leftSection={<PlusIcon size={16} />}>New order</Button>
      </Group>

      <SimpleGrid type="container" cols={{ base: 1, '440px': 2, '860px': 4 }}>
        {statCards}
      </SimpleGrid>

      <Surface level={0} withBorder>
        <Title order={3} fz="md" p="md" c="var(--mantine-color-bright)">
          Recent orders
        </Title>
        <Table.ScrollContainer minWidth={500}>
          <Table verticalSpacing="sm" horizontalSpacing="md">
            <Table.Thead>
              <Table.Tr>
                <Table.Th>Order</Table.Th>
                <Table.Th>Customer</Table.Th>
                <Table.Th>Date</Table.Th>
                <Table.Th>Status</Table.Th>
                <Table.Th ta="right">Amount</Table.Th>
              </Table.Tr>
            </Table.Thead>
            <Table.Tbody>{rows}</Table.Tbody>
          </Table>
        </Table.ScrollContainer>
      </Surface>
    </Stack>
  );
}

import { useState } from 'react';
import { FolderIcon, PlusIcon } from '@phosphor-icons/react';
import { AppShell, Button, NavLink, ScrollArea, Text } from '@mantine/core';
import { footerLinks, projectNames } from './data';
import classes from './Navbar.module.css';

export function Navbar() {
  const [active, setActive] = useState(projectNames[0]);

  const projects = projectNames.map((name) => (
    <NavLink
      key={name}
      href="#"
      variant="rail"
      label={name}
      leftSection={<FolderIcon size={18} />}
      active={name === active}
      onClick={(event) => {
        event.preventDefault();
        setActive(name);
      }}
    />
  ));

  const links = footerLinks.map((link) => (
    <NavLink
      key={link.label}
      href="#"
      variant="rail"
      label={link.label}
      leftSection={<link.icon size={18} />}
      onClick={(event) => event.preventDefault()}
    />
  ));

  return (
    <>
      <AppShell.Section p="md">
        <Text className={classes.heading} mb="sm">
          Projects
        </Text>
        <Button variant="default" fullWidth leftSection={<PlusIcon size={16} />}>
          New project
        </Button>
      </AppShell.Section>
      <AppShell.Section grow component={ScrollArea}>
        {projects}
      </AppShell.Section>
      <AppShell.Section p="md">{links}</AppShell.Section>
    </>
  );
}

import { GearIcon, QuestionIcon } from '@phosphor-icons/react';

const projectTemplates = [
  'Website redesign',
  'Mobile app',
  'Design system',
  'Marketing site',
  'Billing service',
  'Analytics',
  'Onboarding flow',
  'Help center',
];

export const projectNames = Array.from({ length: 40 }, (_, index) => {
  const name = projectTemplates[index % projectTemplates.length];
  const round = Math.floor(index / projectTemplates.length);
  return round === 0 ? name : `${name} ${round + 1}`;
});

